/**
 * The "shopping" set's AppFunctions: one per agent door, each calling its action's handler. Subclassed by the
 * generated ShoppingAppFunctionService, which the app declares in its manifest (ourostack/ouro-ui-android's README says how).
 */
@RequiresApi(Build.VERSION_CODES.BAKLAVA)
@AppFunctionServiceEntryPoint(serviceName = "ShoppingAppFunctionService", appFunctionXmlFileName = "shopping_app_functions")
abstract class BaseShoppingAppFunctionService : AppFunctionService() {

    @AppFunctionDeclaration(isDescribedByKDoc = false)
    @AppFunctionInstruction("Read the person's shopping list: each item's id, name, quantity, unit and whether it is checked.")
    suspend fun getShoppingList(
        @AppFunctionInstruction("Which items to list; all of them when left out.")
        @AppFunctionStringValueConstraint(enumValues = ["all", "unchecked"])
        show: String? = null,
    ): GetShoppingListOutput {
        val showValue = show?.let { GetShoppingListShowValue.of(it) ?: throw AppFunctionInvalidArgumentException("show is not one of all, unchecked.") }
        val input = GetShoppingListInput(show = showValue)
        return GetShoppingListAction.run(input)
    }

    @AppFunctionDeclaration(isDescribedByKDoc = false)
    @AppFunctionInstruction("Add one item to the person's shopping list. Give the name as the person said it; leave quantity and unit out when they gave none.")
    suspend fun addShoppingListItem(
        @AppFunctionInstruction("What to buy, as the person said it, such as \"oat milk\".")
        name: String,
        @AppFunctionInstruction("How many or how much.")
        quantity: Double? = null,
        @AppFunctionInstruction("The unit of the quantity, such as g, cups or cans.")
        unit: String? = null,
    ): AddShoppingListItemOutput {
        val input = AddShoppingListItemInput(name = name, quantity = quantity, unit = unit)
        return AddShoppingListItemAction.run(input)
    }

    @AppFunctionDeclaration(isDescribedByKDoc = false)
    @AppFunctionInstruction("Remove one item from the person's shopping list by its id. Removing an item that is already gone changes nothing.")
    suspend fun removeShoppingListItem(
        @AppFunctionInstruction("The item's id, from get_shopping_list.")
        id: String,
    ) {
        val input = RemoveShoppingListItemInput(id = id)
        RemoveShoppingListItemAction.run(input)
    }

    @AppFunctionDeclaration(isDescribedByKDoc = false)
    @AppFunctionInstruction("Share the person's shopping list with another person, who can then see and change it.")
    suspend fun shareShoppingList(
        @AppFunctionInstruction("The email address of the person to share with.")
        with: String,
        @AppFunctionInstruction("Whether they may change the list, not only see it.")
        canEdit: Boolean? = null,
        @AppFunctionInstruction("A note to send with the invitation. It may run over several lines.")
        message: String? = null,
    ) {
        val input = ShareShoppingListInput(with = with, canEdit = canEdit, message = message)
        // Consequential: the person says yes before it acts.
        val confirm = ShareShoppingListAction.confirm ?: throw AppFunctionDeniedException("Share list needs the person's yes, and this app hasn't said how to ask. Ask the person to do it in the app.")
        confirm(input)
        ShareShoppingListAction.run(input)
    }
}
